    // pc_jobid2mapid(uint16 b_class); -1 (all bits, as the script engine pushes it) for an id with no case.
    internal static long JobIdToMapId(long jobId) => MapIdByJob.TryGetValue((ushort)jobId, out var mapId) ? (long)mapId : -1;
    // pc_mapid2jobid(class_, sex); -1 for a lineage with no case.
    internal static int MapIdToJobId(ulong mapId, int sex) => JobByMapId.TryGetValue(mapId, out var job) ? sex != 0 ? job.Male : job.Female : -1;
